graph = [[1], [0, 2], [1], [4], [3]]
seen = [False] * 5
for start in range(5):
    if seen[start]:
        continue
    group = []
    seen[start] = True
    stack = [start]
    while stack:
        v = stack.pop()
        group.append(v + 1)
        for to in graph[v]:
            if not seen[to]:
                seen[to] = True
                stack.append(to)
    print(group)

