h, w = map(int, input().split())
grid = [input().strip() for _ in range(h)]
seen = [[False] * w for _ in range(h)]
answer = 0
for r in range(h):
    for c in range(w):
        if grid[r][c] == "#" or seen[r][c]:
            continue
        answer += 1
        seen[r][c] = True
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < h and 0 <= ny < w:
                    if grid[nx][ny] == "." and not seen[nx][ny]:
                        seen[nx][ny] = True
                        stack.append((nx, ny))
print(answer)

